// ---------- Cosine Similarity Helper ----------
function cosineSim(a, b) {
  let dot = 0.0, normA = 0.0, normB = 0.0;
  for (let i = 0; i < a.length; i++) {
    dot   += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

// ---------- Config ----------
const threshold = 0.70; // adjust as needed
const deduped   = [];
const results   = [];

// ---------- Main Comparison ----------
for (const item of items) {
  const emb = item.json.embedding;


  let isDup = false;
  let simScore = null;
  let matchUrl = null;
  let matchTitle = null;

  for (const kept of deduped) {
    const keptEmb = kept.json.embedding;
    const sim = cosineSim(emb, keptEmb);

    if (sim > threshold) {
      isDup = true;
      simScore   = sim;
      matchUrl   = kept.json.property_url;
      matchTitle = kept.json.property_title;
      break; // stop at first match
    }
  }

  results.push({
    json: {
      ...item.json,
      duplicate: isDup,
      similarity: simScore,
      matchedUrl: matchUrl,
      matchedTitle: matchTitle
    }
  });

  if (!isDup) deduped.push(item);
}

// ---------- Output ----------
return results;

const embedding = $json.embedding;   // from OpenAI embeddings response
const now = Math.floor(Date.now() / 1000);   // current Unix timestamp
const cutoff = now - (24 * 60 * 60);
         // 12 hours ago in seconds

return [
  {
    json: {
      queryBody: {
        query: embedding,
        limit: 5,
        filter: {
          must: [
            {
              key: "publishedAt",
              range: {
                gte: cutoff,
                lte: now
              }
            }
          ]
        },
        with_payload: true
      }
    }
  }
];

// Input: response from Query Points
// Output: array of related docs in the old format

const results = [];
for (const point of $json.result?.points || []) {
  results.push({
    json: {
      document: {
        pageContent: point.payload.content || "",
        metadata: {
          url: point.payload.url || null,
          urlHash: point.payload.urlHash || null,
          publishedAt: point.payload.publishedAt || null
        }
      },
      score: point.score || 0
    }
  });
}

return results;

